package com.autoops.execution.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="step_runs")public class StepRun{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="machine_run_id",nullable=false)private Long machineRunId;@Column(name="workflow_step_id")private Long workflowStepId;@Column(nullable=false)private String status="PENDING";@Column(name="original_command",columnDefinition="text")private String originalCommand;@Column(name="resolved_command",columnDefinition="text")private String resolvedCommand;@Column(columnDefinition="text")private String stdout;@Column(columnDefinition="text")private String stderr;@Column(name="exit_code")private Integer exitCode;@Column(name="attempt_number",nullable=false)private Integer attemptNumber=1;@Column(name="retry_of_step_run_id")private Long retryOfStepRunId;@Column(name="started_at")private Instant startedAt;@Column(name="finished_at")private Instant finishedAt;public Long getId(){return id;}public Long getMachineRunId(){return machineRunId;}public String getResolvedCommand(){return resolvedCommand;}public Integer getAttemptNumber(){return attemptNumber;}public void setMachineRunId(Long v){machineRunId=v;}public void setStatus(String v){status=v;}public void setResolvedCommand(String v){resolvedCommand=v;}public void setAttemptNumber(Integer v){attemptNumber=v;}public void setRetryOfStepRunId(Long v){retryOfStepRunId=v;}}
